import type { Article, ArticleSection, Chapter, GlossaryTerm, RichText } from '../types';

const subjectId = 'fuehrung-zusammenarbeit';
const updatedAt = Date.UTC(2026, 10, 18);

type Paragraph = string | (string | RichText)[];
type Lesson = {
  id: string;
  parent?: string;
  number: string;
  title: string;
  intro: string;
  sections: ArticleSection[];
};

const id = (name: string) => `fz-${name}`;
const termId = (name: string) => `fz-begriff-${name}`;
const term = (name: string, text: string): RichText => ({ text, termId: termId(name) });
const link = (name: string, text: string): RichText => ({ text, articleId: id(name) });

function section(id: string, title: string, ...paragraphs: Paragraph[]): ArticleSection {
  return {
    id,
    title,
    paragraphs: paragraphs.map(paragraph => (typeof paragraph === 'string' ? [paragraph] : paragraph)
      .map(part => typeof part === 'string' ? { text: part } : part)),
  };
}

function question(prompt: string, answer: string): ArticleSection {
  return {
    ...section('transferfrage', 'Selbstkontrolle', prompt),
    hint: { label: 'SELBSTKONTROLLE', title: 'Musterantwort', content: answer },
  };
}

