export const chapters: Chapter[] = lessons.map(lesson => ({
  id: id(lesson.id),
  subjectId,
  ...(lesson.parent ? { parentId: id(lesson.parent) } : {}),
  articleId: id(lesson.id),
  number: lesson.number,
  title: lesson.title,
}));

